INSERT INTO `boss_data` VALUES ('ANDROID_13','Android 13',0,'252,253,254,-1,-1,-1',12055,'500000000','104','1:7:10000,17:7:1000','|-1|Sôn..gôku\n|-2|Lại là tiến sĩ Kôrê à.. rốt cuộc ông ta đã tạo ra bao nhiêu rôbốt nhân tạo thế nhỉ?\n|-1|Bọn ta là rôbốt sát thủ, sinh ra từ máy tính ngài Kôrê,..\n|-1|..cho một mục tiêu duy nhất là giết Sôngôku!\n|-2|Máy tính? Để giết Gôku sao?\n|-1|Mong muốn trả thù Gôku của ngài Kôrê đã được lưu hết vào máy tính..\n|-1|.., Bọn ta sinh ra từ lòng căm thù ngày một tăng bên trong chiếc máy tính có chứa mong muốn trả thù\n|-1|Mục tiêu của bọn ta chỉ là Gôku, nhưng mà.. nếu ngươi mà cản đường thì là chuyện khác!','|-1|Sao thế hả? Ta mới chỉ khởi động thôi mà!\n|-2|Ngươi đánh giá thấp bọn ta quá đấy!\n|-2|Đừng có tưởng bở, lũ sâu bọ!\n|-1|Nếu có ý định gây trở ngại cho cuộc chiến giữa ta và Sôngôku, thì ta cũng sẽ giết ngươi ngay lập tức\n|-2|Ngươi tưởng ta để cho ngươi giết được ta ngay à?\n|-2|Đúng là mạnh mồm thật đấy!\n|-2|Đỡ này','|-1|Sô..Sông...gôku.....',0,'CALL_BY_ANOTHER',''),('ANDROID_14','Android 14',0,'246,247,248,-1,-1,-1',12000,'50000000','104','1:7:10000,17:7:1000','|-2|Các ngươi là ai?\n|-2|Ta không thể cảm nhận được khí của các ngươi, các ngươi không phải là con người đúng chứ?\n|-2|Ta hiểu rồi, các ngươi là rôbốt sát thủ do tiến sĩ Kôrê tạo ra chứ gì?','','|0|Số 14 và số 15 tiêu tùng cả rồi à?',600,'DEFAULT_APPEAR','-129,-131'),('ANDROID_15','Android 15',0,'261,262,263,-1,-1,-1',19200,'500000000','104','1:7:10000,17:7:1000','','','|-2|Thì ra vẫn chỉ là một đống sắt vụn!',0,'APPEAR_WITH_ANOTHER',''),('ANDROID_19','Android 19',0,'249,250,251,-1,-1,-1',12200,'30000000','96,94,93','1:7:1000,17:7:10000','','|-1|Oải rồi hả?\n|-1|Ê cố lên nhóc\n|-1|Chán\n|-1|Ngươi sẽ không bao giờ thắng được đâu!!\n|-2|Ngươi vừa hút được nhiều rồi đấy, nhưng giờ thì đừng hòng!!','',0,'APPEAR_WITH_ANOTHER',''),('BERUS','Thần Hủy Diệt Berrus',0,'508,509,510,-1,-1,-1',150000,'500000000','202,203','3:1:604,0:7:558','','','',1800,'DEFAULT_APPEAR',''